INSERT INTO `products` (`id`, `name`, `slug`, `category`, `price`, `unit`, `short_desc`, `description`, `image`, `featured`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
('1', 'BetterLife Honey', 'betterlife-honey', 'Honey', '30000.00', '1 kg jar', 'Sweet, natural honey from BetterLife Agro Tourism Farm.', 'BetterLife Honey is packed by BetterLife Agro Tourism Farm. Like everything from BetterLife Agro Tourism Farm, it is made from what community farmers produce. The farm buys their surplus, adds value and sells it, so every purchase helps keep that market open for refugee, displaced and host-community families.', 'assets/img/product-honey-real.jpg', '1', '1', '1', '2026-09-28 20:26:27', '2026-10-03 15:26:55'),
('2', 'Golden Comb Honey', 'golden-comb-honey', 'Honey', '32000.00', '400g jar', 'Honeycomb harvested whole for the purest, most natural honey experience.', 'For the purist, our Golden Comb Honey is harvested whole from the hive and bottled exactly as nature made it. Chew the comb or let it melt over warm bread. Either way, you are tasting honey the way it was meant to be enjoyed, straight from our apiaries around the BetterLife Farm.', 'assets/img/product-honey-real.jpg', '0', '0', '2', '2026-09-28 20:26:27', '2026-10-04 08:27:59'),
('3', 'BetterLife Ghee', 'betterlife-ghee', 'Ghee', '30000.00', '1 kg jar', 'Organic ghee made from 100% pure cow butter.', 'BetterLife Organic Ghee is made from 100% pure cow butter and is a natural source of energy for cooking. Contains milk. Like everything from BetterLife Agro Tourism Farm, it is made from what community farmers produce. The farm buys their surplus, adds value and sells it, so every purchase helps keep that market open for refugee, displaced and host-community families.', 'assets/img/product-ghee-real.jpg', '1', '1', '2', '2026-09-28 20:26:27', '2026-10-03 15:26:55'),
('4', 'Cultured Butter Ghee', 'cultured-butter-ghee', 'Ghee', '35000.00', '350ml jar', 'A deeper, cultured flavour profile made from fermented cream.', 'Our Cultured Butter Ghee starts with fermented cream for a deeper, tangier flavour before it is slow-clarified into golden ghee. It is a small-batch product made by our farm cooperative, prized by chefs for its aroma and long shelf life without refrigeration.', 'assets/img/product-ghee-real.jpg', '0', '0', '4', '2026-09-28 20:26:27', '2026-10-03 15:13:59'),
('5', 'BetterLife Yoghurt, Vanilla', 'betterlife-yoghurt-vanilla', 'Yoghurt', '7000.00', '1 litre', 'BetterLife Yoghurt in vanilla flavour.', 'BetterLife Yoghurt in vanilla flavour, also available in strawberry. Like everything from BetterLife Agro Tourism Farm, it is made from what community farmers produce. The farm buys their surplus, adds value and sells it, so every purchase helps keep that market open for refugee, displaced and host-community families.', 'assets/img/product-yoghurt-real.jpg', '1', '1', '4', '2026-09-28 20:26:27', '2026-10-03 15:26:55'),
('6', 'BetterLife Yoghurt, Strawberry', 'betterlife-yoghurt-strawberry', 'Yoghurt', '7000.00', '1 litre', 'BetterLife Yoghurt in strawberry flavour.', 'BetterLife Yoghurt in strawberry flavour, also available in vanilla. Like everything from BetterLife Agro Tourism Farm, it is made from what community farmers produce. The farm buys their surplus, adds value and sells it, so every purchase helps keep that market open for refugee, displaced and host-community families.', 'assets/img/product-yoghurt-real.jpg', '1', '1', '3', '2026-09-28 20:26:27', '2026-10-03 15:26:55'),
('7', 'BetterLife Organic Boost', 'betterlife-organic-boost', 'Farm Inputs', '100000.00', '20 litre jerrycan', 'Organic liquid fertilizer that improves soil fertility and boosts crop yield naturally.', 'BetterLife Organic Boost is an eco-friendly, organic liquid fertilizer produced at BetterLife Agro Tourism Farm. Safe for plants, people and the planet, it improves soil fertility and boosts crop yield naturally: the same climate-smart, sustainable approach we teach farmers across our programs, now bottled for your own garden or farm.', 'assets/img/product-organic-boost.jpg', '1', '1', '5', '2026-09-28 20:26:27', '2026-10-04 08:27:59');
INSERT INTO `team_members` (`id`, `name`, `role`, `category`, `bio`, `photo`, `email`, `facebook`, `twitter`, `linkedin`, `sort_order`, `status`, `created_at`) VALUES
('1', 'Denise Ayebare', 'Executive Director & Founder', 'leadership', 'Denise Ayebare is a Ugandan lawyer, climate justice advocate and youth leader who founded BetterLife International at nineteen. She currently serves as Secretary for External Affairs of Uganda\'s National Youth Council and has represented young people in regional and international climate-policy processes. Denise previously served as Prime Minister of Uganda\'s Fifth National Youth Parliament and has contributed to youth leadership, climate resilience and locally led development across Africa. Recognised in the Forbes Africa 30 Under 30 Class of 2026, she leads BetterLife\'s work with women, refugees, young people and vulnerable communities, connecting sustainable livelihoods with policy influence and long-term institutional change.', 'assets/img/team/denise-ayebare.jpg', NULL, NULL, NULL, NULL, '1', '1', '2026-09-28 20:26:27'),
('2', 'Samuel Ahabwe', 'Head of Finance', 'leadership', 'Samuel Ahabwe serves as Head of Finance at BetterLife International, supporting the organisation\'s financial planning, accountability and responsible use of resources. He oversees budgeting, expenditure tracking, financial documentation and reporting across BetterLife\'s programmes and country operations. Working closely with the executive and programme teams, Samuel helps ensure that organisational resources are aligned with approved activities and deliver value to the communities BetterLife serves. His role is central to strengthening internal controls, supporting donor compliance and improving the financial systems required for sustainable growth.', 'assets/img/team/ahabwe-samuel.jpg', NULL, NULL, NULL, NULL, '3', '1', '2026-09-28 20:26:27'),
('3', 'Douglas Drake Onen', 'Chief Operations Officer', 'staff', 'Douglas Drake Onen is a legal professional and governance advocate serving as Chief Operations Officer at BetterLife International. Educated at Uganda Christian University, he has gained experience in constitutional governance and legal research, with a particular interest in the rule of law. At BetterLife, Douglas coordinates organisational operations and helps translate institutional strategy into effective programme delivery. He works across country teams to strengthen internal systems, staff coordination, compliance and implementation. His legal background supports BetterLife\'s commitment to accountable governance, responsible partnerships and community-centred development. Douglas brings structured leadership to an organisation operating across different national contexts and serving communities facing displacement, poverty and climate vulnerability.', 'assets/img/team/douglas-drake-onen.jpg', NULL, NULL, NULL, NULL, '7', '1', '2026-09-28 20:26:27'),
('4', 'Shallon Kaitesi', 'Administrator', 'staff', 'Shallon Kaitesi is an environmental advocate and administrator with experience in youth-led climate action and programme coordination. Before joining BetterLife International, her work spanned environmentalism, debate, Rotaract and programme coordination with Cherish Aid Foundation. At BetterLife, Shallon supports the organisation\'s daily administration, internal coordination, documentation and communication across teams. She helps ensure that meetings, records, schedules and operational processes are organised effectively, enabling programme staff to concentrate on community delivery. Her combination of administrative ability and commitment to climate justice strengthens BetterLife\'s youth-led character and its work to build sustainable, inclusive opportunities for vulnerable communities across Africa.', 'assets/img/team/kaitesi-shallon.jpg', NULL, NULL, NULL, NULL, '4', '1', '2026-09-28 20:26:27'),
('5', 'Charity Kembabazi', 'Board Member', 'board', 'Charity Kembabazi is a social scientist, monitoring and evaluation expert, and community development professional serving on the Board of BetterLife International. She brings experience in local government and a practical understanding of how public institutions and community organisations can work together to improve people’s lives.\n\nPreviously serving as a Community Development Officer, Charity worked directly with communities. That experience brings an important perspective to BetterLife’s governance: understanding local priorities, the barriers people face in accessing support, and the relationships needed to sustain community programmes.\n\nHer expertise in monitoring and evaluation complements this background. She brings attention to how programmes are planned, how progress is assessed and how evidence informs decisions. This is particularly relevant to BetterLife’s work connecting training with food production, livelihoods and greater household security.\n\nAs a board member, Charity contributes a combination of community experience, social-science knowledge and an emphasis on accountability. Her background helps inform the organisation’s strategic direction and its commitment to programmes shaped by the people they serve.', 'assets/img/team/kembabazi-charity.jpg', NULL, NULL, NULL, NULL, '20', '1', '2026-09-28 20:26:27'),
('6', 'Comboni Daniel Mutabaazi', 'Country Manager, Tanzania', 'staff', 'Comboni Daniel Mutabaazi serves as BetterLife International\'s Country Manager in Tanzania, leading the organisation\'s national programmes and partnerships. He coordinates community engagement, programme implementation and relationships with local authorities, organisations and other stakeholders. His work helps ensure that BetterLife\'s interventions respond to the realities of the communities in which they are delivered, particularly in sustainable agriculture, climate resilience, youth livelihoods and support for vulnerable households. Daniel also connects the Tanzania team with BetterLife\'s wider regional leadership, strengthening reporting, learning and coordination across countries. His role reflects BetterLife\'s commitment to locally grounded leadership and solutions shaped by the people closest to the challenges being addressed.', 'assets/img/team/comboni-mutabaazi.jpg', NULL, NULL, NULL, NULL, '12', '1', '2026-09-28 20:26:27'),
('7', 'Becky Alec', 'Country Manager, South Sudan', 'staff', 'Becky Alec serves as BetterLife International\'s Country Manager in South Sudan, coordinating programmes that support young people, displaced families and communities affected by economic and climate pressures. She is also active in competitive debate, including international adjudication and South Sudan\'s debate community. This background brings strong communication, analysis and youth-engagement skills to her work. At BetterLife, Becky oversees local implementation, team coordination, stakeholder engagement and programme reporting. She helps ensure that activities are rooted in community priorities while remaining connected to BetterLife\'s regional mission of strengthening livelihoods, resilience, social cohesion and meaningful opportunities for young people across Africa.', 'assets/img/team/alec-becky.jpg', NULL, NULL, NULL, NULL, '10', '1', '2026-09-28 20:26:27'),
('8', 'Victoria Kinobe', 'Country Manager, DR Congo', 'staff', 'Victoria Kinobe Nakatudde is an engineer with experience in water resources, catchment-management planning, environmental and social impact assessment, and stakeholder engagement. Her professional work has included water-resources planning and regulation, alongside participation in regional and international climate discussions. As BetterLife International\'s Country Manager for the Democratic Republic of Congo, Victoria brings technical knowledge of water, environmental management and community engagement to the organisation\'s programmes. She supports locally appropriate interventions addressing climate vulnerability, livelihoods and sustainable resource use. Her experience helps connect technical environmental planning with the everyday needs of communities, strengthening BetterLife\'s ability to design practical, evidence-informed and environmentally responsible programmes.', 'assets/img/team/victoria-kinobe-cop29.jpg', NULL, NULL, NULL, NULL, '11', '1', '2026-09-28 20:26:27'),
('9', 'Ian Agaba', 'Programs Coordinator', 'staff', 'Ian Agaba is a Ugandan lawyer, climate justice advocate, writer and Pan-African youth leader serving as Programmes Coordinator at BetterLife International. His public work includes climate advocacy, youth engagement, public speaking and discussions on climate-related displacement and its effects on children. Ian has also participated in university debate, developing skills in research, policy analysis and persuasive communication. At BetterLife, he supports programme design, implementation, coordination and reporting across the organisation\'s thematic and country teams. He helps connect community experiences with wider conversations about climate justice, livelihoods and youth participation, ensuring that BetterLife\'s programmes remain responsive, practical and grounded in the needs of vulnerable communities.', 'assets/img/team/agaba-ian.jpg', NULL, NULL, NULL, NULL, '8', '1', '2026-09-28 20:26:27'),
('10', 'Desmond Dorvlo', 'Country Manager, Ghana', 'staff', 'Desmond Dorvlo is a Ghanaian communications professional, researcher, writer and debater serving as BetterLife International\'s Country Manager in Ghana. He studied at Kwame Nkrumah University of Science and Technology, where he has worked as a teaching and research assistant in English. His research interests include African literature, political communication, governance, gendered language and public discourse. Desmond has also worked in communications and external relations and produced writing on Ghanaian culture and travel. At BetterLife, he brings together research, storytelling and stakeholder engagement to coordinate programmes, partnerships and community relationships, strengthening the organisation\'s presence and locally led work in Ghana.', 'assets/img/team/desmond-dorvlo.jpg', NULL, NULL, NULL, NULL, '13', '1', '2026-09-28 20:26:27'),
('11', 'Janice Nkajja', 'Head of Communications & Advocacy', 'staff', 'Janice Nkajja is a Ugandan communicator, public speaker and youth advocate serving as Head of Communications and Advocacy at BetterLife International. She was recognised as a co-winner in the speech category of Uganda\'s 2021 National Speech and Debate Championship and has subsequently contributed to debate and youth-communication initiatives. Janice has also served in public-relations work with Signals from the Grassroots. At BetterLife, she leads storytelling, media engagement, advocacy communication and the documentation of community experiences. She helps ensure that the voices of women, refugees, young people and smallholder farmers are represented accurately and with dignity, connecting their realities to partners, policymakers and wider public audiences.', 'assets/img/team/nkajja-janice.jpg', NULL, NULL, NULL, NULL, '6', '1', '2026-09-28 20:26:27'),
('12', 'Desire Ainembabazi', 'Regional Director', 'leadership', 'Desire Ainembabazi is a nutrition and dietetics professional, youth nutrition advocate and Regional Director at BetterLife International. Desire’s work connects food, health and livelihoods, bringing a nutrition perspective to an organisation focused on helping communities grow food and build sustainable sources of income.\n\nPreviously, Desire served as Head of Operations at BetterLife Agro Tourism Farm. This operational background complements expertise in nutrition and dietetics, connecting the practical demands of agricultural work with the importance of nutritious food and household wellbeing.\n\nDesire’s public professional profile highlights advocacy for nutrition, food and wellness, alongside experience in outreach at BetterLife. This combination brings both technical knowledge and community engagement experience to the regional role.\n\nAt BetterLife, Desire contributes a perspective that connects agricultural production with the people it serves. Across farming, livelihoods and school-feeding activities, that perspective helps keep the nutritional value of food central to the organisation’s wider commitment to food security.', 'assets/img/team/desire-ainembabazi.jpg', NULL, NULL, NULL, NULL, '2', '1', '2026-09-28 20:26:27'),
('13', 'Sedrick Otolo', 'Board Member', 'board', 'Sedrick Otolo is a Ugandan technology entrepreneur, author and youth mentor serving on the Board of BetterLife International. His work connects digital innovation, enterprise and community development, with a particular focus on creating opportunities for young people in Northern Uganda.\n\nAs Team Lead at KaKebe Technologies, Sedrick works on technology-driven initiatives that respond to local needs. His technical background includes a diploma in Networking and Cyber Security from ISBAT University, alongside experience in public speaking, coaching and creative writing.\n\nBeyond his technology work, Sedrick engages young people through mentorship and conversations about leadership, character and entrepreneurship. He is a co-founder of The Unlimited Youths and the author of Building Great Character, reflecting his wider interest in helping young people develop their abilities and pursue opportunities.\n\nAt BetterLife, Sedrick brings an entrepreneurial and technology-focused perspective to board discussions. His background is relevant to the organisation’s digital agriculture, youth skills and enterprise work, contributing to its strategic thinking on how practical innovation can support food security and sustainable livelihoods.', 'assets/img/team-sedrick-otolo.webp', NULL, NULL, NULL, NULL, '22', '1', '2026-09-28 20:26:27'),
('14', 'Felicia Davis', 'Board Member', 'board', 'Felicia Davis is a climate justice advocate and sustainability leader with more than two decades of experience connecting environmental action, education and community empowerment. She serves on the Board of BetterLife International, bringing an international perspective on equitable development and the role of communities in shaping climate solutions.\n\nIn 2016, Felicia co-founded the HBCU Green Fund to help finance sustainability projects at Historically Black Colleges and Universities. Her work promotes energy efficiency, renewable energy and sustainable practices while creating opportunities for students and emerging leaders to participate in the climate movement. She also directed the UNCF Building Green Initiative, advancing sustainability at Black, Hispanic-serving and tribal colleges and universities.\n\nFelicia’s commitment to climate justice spans local organising and international engagement. Her environmental career has included work with Ozone Action and Greenpeace, alongside leadership in clean-air advocacy. She was a founding board member of Green 2.0, an organisation working to increase racial diversity in environmental leadership, and has helped connect sustainability advocates across Africa and the diaspora.\n\nIn 2023, the Intentional Endowments Network recognised her with its inaugural Leadership Award for her contributions to climate justice and her support for women and emerging environmental leaders.\n\nAt BetterLife, Felicia’s experience strengthens the board’s perspective on climate resilience, inclusive partnerships and community leadership. Her background aligns closely with the organisation’s commitment to helping women, young people and communities build secure livelihoods and shape their own futures.', 'assets/img/board-felicia-davis.jpg', NULL, NULL, NULL, NULL, '19', '1', '2026-09-28 20:26:27'),
('15', 'Mohamed Nasheed', 'Board Member', 'board', 'In 2008, Nasheed became the first democratically elected president of the Maldives. His administration focused on democratic reforms, human rights and environmental sustainability, and he gained international acclaim for organizing the world\'s first underwater cabinet meeting on climate change.', 'assets/img/board-nasheed.jpg', NULL, NULL, NULL, NULL, '21', '0', '2026-09-28 20:26:27'),
('16', 'Pamela Musimenta', 'Board Member', 'board', 'Pamela Musimenta is a Ugandan water resources engineer, environmentalist and climate justice advocate working with the Ministry of Water and Environment. Her professional interests span water resources planning and regulation, hydraulic engineering, environmental compliance and access to clean, safe water. A UNFCCC advocate and beVisioneers Fellow, Pamela leads community-based work addressing deforestation, land degradation, soil erosion and flood risk through tree nurseries and soil and water conservation. She brings to BetterLife International\'s Board a combination of government experience, technical expertise and grassroots climate leadership, strengthening the organisation\'s work in renewable energy, sustainable agriculture, water security and community resilience across Africa.', 'assets/img/team/pamela-musimenta.jpg', NULL, NULL, NULL, NULL, '21', '1', '2026-09-28 20:26:27'),
('17', 'Bob Natifu', 'Board Member', 'board', 'Bob Natifu is a Ugandan climate-policy practitioner and climate-education advocate serving on the Board of BetterLife International. He is the Acting Commissioner for Climate Change at Uganda’s Ministry of Water and Environment, bringing experience in national climate coordination, public engagement and international cooperation.\n\nHis career has included climate-change outreach and support for Uganda’s National Climate Change Learning Strategy. As a UN CC:Learn Ambassador and Uganda’s focal point for Action for Climate Empowerment, he has helped advance education, training, public awareness and participation as essential parts of the climate response. In 2019, he co-facilitated the seventh Action for Climate Empowerment Dialogue during the Bonn Climate Change Conference.\n\nA professional journalist and graduate of Uganda Christian University, Bob combines policy experience with a background in communication. His interests span climate-risk perceptions, adaptation, governance, climate finance and the role of women in natural-resource management. He has also undertaken international training in climate adaptation and ecosystem-based approaches.\n\nAt BetterLife, this background brings a valuable policy and institutional perspective to the board. His experience is relevant to the organisation’s work connecting food security, sustainable livelihoods and climate resilience, alongside its commitment to community participation and youth learning.', 'assets/img/board-bob-natifu.jpg', NULL, NULL, NULL, NULL, '23', '1', '2026-09-28 20:26:27'),
('18', 'Edwin Namakanga', 'Outreach Coordinator', 'staff', 'Edwin Namakanga is a Ugandan climate justice advocate and demographer with experience in public engagement, youth mobilisation and advocacy on climate displacement. He serves as Outreach Coordinator at BetterLife International, bringing this background to the organisation’s relationships with communities and wider networks.\n\nActive in climate advocacy since 2019, Edwin has organised campaigns and worked with Fridays for Future MAPA and the Rise Up Movement. He founded Refugees for Future Uganda and supports climate migrants through the Ingo Weffe Initiative. His international engagement includes participation in COP26, COP27 and COP28, where he advocated for climate justice and loss-and-damage funding.\n\nAt BetterLife, his outreach role connects the organisation’s practical work with opportunities for participation, collaboration and public understanding. His experience is particularly relevant to programmes involving young people, refugees and communities facing climate pressures, helping connect local concerns with broader conversations about food security, livelihoods and resilience.', 'assets/img/team/edwin-namakanga.jpg', NULL, NULL, NULL, NULL, '9', '1', '2026-10-04 10:00:27'),
('19', 'Alison Linda Ninsiima', 'Monitoring and Evaluation Specialist', 'staff', 'Alison Linda Ninsiima is a Ugandan development practitioner and climate and water advocate with experience in youth programme coordination, stakeholder engagement and community participation. She serves as Monitoring and Evaluation Specialist at BetterLife International, bringing a background that connects practical community work with national and international policy discussions.\n\nHer experience includes youth programme coordination at the Rural Gender and Development Association, where her work has covered programme design and implementation, climate justice, gender equality, digital community development, and water, sanitation and hygiene. She has also worked with the National Water and Sewerage Corporation and contributed to the youth subcommittee organising Uganda Water Week.\n\nAs Focal Point for the Ugandan Youth Parliament for Water, Alison advocates for young people to have a meaningful role in water governance. Her international engagement includes speaking on water finance at the 10th World Water Forum and participating in the Dakar meetings leading towards the 2026 UN Water Conference.\n\nAlison brings this combination of programme experience, community engagement and policy advocacy to BetterLife’s monitoring and evaluation work. Her background offers a valuable perspective on understanding how programmes respond to local needs and how evidence can guide better decisions across food security, livelihoods and climate resilience.', 'assets/img/team/alison-nimusiima.jpg', NULL, NULL, NULL, NULL, '5', '1', '2026-10-04 10:23:06'),
('20', 'Jackson Odida', 'Legal and Compliance Officer', 'staff', 'Jackson Odida is a Ugandan legal professional whose work brings together law, youth leadership and environmental engagement. He serves as Legal and Compliance Officer at BetterLife International, contributing a legal perspective to the organisation’s work with communities and partners.\n\nJackson’s public profile identifies him as the 22nd Guild Speaker of Gulu University and a beVisioneers Fellow. These experiences connect his legal background with student leadership and environmental innovation, bringing a useful combination of institutional engagement and community-focused thinking to BetterLife.\n\nWithin the organisation, his role supports sound governance, clear agreements and responsible programme delivery. His contribution helps strengthen the legal foundations behind BetterLife’s partnerships and operations as its food-security, livelihoods and climate-resilience work grows.', 'assets/img/team/jackson-odida.jpg', NULL, NULL, NULL, NULL, '9', '1', '2026-10-06 10:56:51');
