INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category_id`, `excerpt`, `content`, `featured_image`, `author`, `status`, `views`, `published_at`, `created_at`, `updated_at`) VALUES
('1', 'Climate Justice: Beyond Financial Transactions to Protect the Vulnerable', 'climate-justice-beyond-financial-transactions', '2', 'Climate justice is not merely about financial transactions to protect the environment. It embodies the fight for fairness for the communities least responsible for the crisis, yet most affected by it.', '<p>Climate justice is not merely about financial transactions to protect the environment. It embodies the fight for fairness for the communities least responsible for the climate crisis, yet most affected by its consequences.</p><p>Across Uganda, South Sudan, Tanzania, Ghana and the DR Congo, the families BetterLife International works with are on the frontline of a crisis they did little to cause — unpredictable rains, shrinking grazing land, and displacement driven by environmental stress. True climate justice means channelling resources, skills and decision-making power directly to these communities, not just discussing figures in international finance rooms.</p><p>That is why our approach pairs climate education with tangible livelihoods: green skills training, climate-smart agriculture, and renewable energy access such as biogas and boreholes. When a family can irrigate a field with solar power or cook with biogas instead of charcoal, climate justice becomes something they can hold in their hands, not just a policy conversation.</p><p>We continue to advocate for financing that reaches the last mile — the refugee-hosting districts and rural communities that are too often left out of climate finance altogether.</p>', 'assets/img/blog-climate-justice.jpg', 'Admin', 'published', '0', '2024-10-26 09:00:00', '2026-09-28 20:26:27', '2026-09-28 20:26:27'),
('2', 'Climate Change: Amplifying Extreme Weather and Displacement', 'climate-change-extreme-weather-displacement', '2', 'Climate change significantly heightens the risks of extreme weather events — storms, floods, wildfires — and the displacement that follows them.', '<p>Climate change significantly heightens the risks of extreme weather events — such as storms, floods, wildfires, and droughts — and the human displacement that so often follows in their wake.</p><p>In the regions where BetterLife International works, we see this firsthand: families who already fled conflict now facing floods that destroy their new farmland, or droughts that fail the very crops meant to rebuild their food security. Displacement driven by climate stress is compounding an already fragile humanitarian situation across Sub-Saharan Africa.</p><p>Our response combines immediate resilience-building — climate-smart agriculture, water access through boreholes, and renewable energy — with long-term climate education through our Green Libraries and Eco Clubs, reaching thousands of students with the knowledge to adapt and lead.</p><p>Addressing climate-driven displacement requires both humanitarian urgency and sustained investment in local adaptation. It is a challenge we are meeting one community, one borehole, one biogas plant at a time.</p>', 'assets/img/blog-extreme-weather.jpg', 'Admin', 'published', '0', '2024-10-14 09:00:00', '2026-09-28 20:26:27', '2026-09-28 20:26:27'),
('3', 'Congratulations to Dr. Okello Sharon Nagenjwa on Her PhD and Outstanding Community Impact!', 'dr-okello-sharon-nagenjwa-phd', '4', 'We are happy to celebrate the remarkable journey of Dr. Okello Sharon Nagenjwa, who was recently awarded her PhD after years of dedicated research and community impact.', '<p>We are happy to celebrate the remarkable journey of Dr. Okello Sharon Nagenjwa, who was recently awarded her PhD after years of dedicated research and community impact work across Uganda\'s agricultural and refugee-hosting communities.</p><p>Dr. Nagenjwa\'s research has directly informed several of BetterLife International\'s programs in sustainable agriculture and climate-smart farming, helping bridge the gap between academic research and practical, farmer-led solutions.</p><p>Her achievement reflects the spirit of BetterLife International\'s mission: that those closest to a challenge are often best placed to solve it. We congratulate Dr. Nagenjwa and look forward to continued collaboration as we grow our agricultural and livelihoods programs, including the BetterLife Farm.</p>', 'assets/img/blog-sharon-phd.png', 'Admin', 'published', '0', '2024-09-29 09:00:00', '2026-09-28 20:26:27', '2026-09-28 20:26:27'),
('4', 'The Importance of Civic Education in Uganda: An Evaluative Analysis', 'importance-of-civic-education-in-uganda', '4', 'Civic education plays a crucial role in the development of any democratic society, yet in Uganda it remains under-prioritized in many communities.', '<p>Civic education plays a crucial role in the development of any democratic society, yet in Uganda it remains under-prioritized in many communities, particularly among youth and displaced populations.</p><p>Through our Climate Education and Awareness programme, BetterLife International has seen how civic literacy and environmental literacy reinforce one another — young people who understand their rights and responsibilities are also more likely to take an active role in protecting their environment and holding leaders accountable for it.</p><p>We believe civic education should be woven into every level of schooling, not treated as an afterthought. It is one of the quiet foundations of the resilient, self-reliant communities we work to build.</p>', 'assets/img/blog-civic-education.jpg', 'Admin', 'published', '0', '2024-09-20 09:00:00', '2026-09-28 20:26:27', '2026-09-28 20:26:27'),
('5', 'The Naked Truth of Corruption: A Critical Analysis of Uganda\'s Socioeconomic State and Youth-Led Activism', 'naked-truth-of-corruption-uganda', '4', 'Uganda is currently grappling with a critical socio-political issue: rampant corruption, which has become deeply embedded and is fuelling youth-led activism.', '<p>Uganda is currently grappling with a critical socio-political issue: rampant corruption, which has become deeply embedded in public institutions and continues to undermine development outcomes for ordinary citizens.</p><p>At BetterLife International, we see the downstream effects of this every day — resources that should reach vulnerable communities are too often diverted, delayed, or diminished. This is part of why we are youth-led: young people across our five countries of operation are refusing to accept corruption, inequality, or environmental destruction as the status quo.</p><p>Youth-led activism, paired with transparent, community-owned programs like our farm cooperatives and green-skills training, is one practical way to build systems that are accountable from the ground up.</p>', 'assets/img/blog-corruption.jpg', 'Admin', 'published', '0', '2023-09-06 09:00:00', '2026-09-28 20:26:27', '2026-09-28 20:26:27');
INSERT INTO `testimonials` (`id`, `quote`, `author_name`, `author_role`, `photo`, `sort_order`, `status`, `created_at`) VALUES
('1', 'The training I received in organic dairy farming changed everything for my family. Today I supply milk for the farm\'s own ghee and yoghurt.', 'A Farmer, Rukungiri Cooperative', 'BetterLife Farm Partner', NULL, '1', '1', '2026-09-28 20:26:27'),
('2', 'Beekeeping gave me an income for the first time since I fled home. Every jar of honey we sell carries our story forward.', 'A Beekeeper', 'Refugee-led Livelihoods Program', NULL, '2', '1', '2026-09-28 20:26:27');
