INSERT INTO `content_items` (`id`, `page`, `section_key`, `title`, `subtitle`, `body`, `image`, `cta_label`, `cta_href`, `extra`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
('1', 'about', 'how_we_work', 'We Start by Listening', '', 'We work through women’s groups, farmer groups, refugee and host-community structures, schools, community organisations and local facilitators. These groups help us understand what is changing, what has already been tried and what people can realistically sustain.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('2', 'about', 'how_we_work', 'People Learn by Seeing and Doing', '', 'A technique explained in a workshop can remain abstract. A garden that is producing through a dry spell is harder to dismiss. We use demonstration sites, local-language facilitation, peer learning and community champions so that people can see, question and test new practices.', NULL, NULL, NULL, NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('3', 'about', 'how_we_work', 'Training Must Lead Somewhere', '', 'Knowledge matters, but so do tools, money and customers. We connect learning to starter inputs, savings, finance, business support, services and markets wherever possible.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('4', 'about', 'how_we_work', 'We Build with Existing Groups', '', 'We strengthen existing groups and local institutions instead of creating temporary committees that disappear when a project closes. Local ownership is not an exit strategy added at the end. It is part of the design from the beginning.', NULL, NULL, NULL, NULL, '30', '1', '2026-08-31 16:53:16', '2026-10-02 11:28:55'),
('5', 'about', 'how_we_work', 'We Follow What Changes', '', 'We use monitoring data, participant feedback and field observation to understand whether people are applying what they learnt and whether that application is improving food, income, confidence or resilience.', NULL, NULL, NULL, NULL, '40', '1', '2026-08-31 16:53:16', '2026-10-02 11:28:55'),
('6', 'about', 'who_we_work_with', 'Women and Girls', '', 'Women hold much of the responsibility for food, water and household care, yet often have less access to land, money, technology and decision-making. Our programmes pay attention to the barriers that shape participation, including time, phone access, mobility, confidence and social norms.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('7', 'about', 'who_we_work_with', 'Children and Young People', '', 'We work with children and young people through schools, youth centres, climate education, digital learning, livelihoods, leadership and innovation programmes. They are not only preparing for the future; they already have ideas and decisions to contribute today.', NULL, NULL, NULL, NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('8', 'about', 'who_we_work_with', 'Refugees and Displaced Families', '', 'Our programmes support people affected by displacement to rebuild their ability to produce food, earn, save and take part in the local economy. We work with refugees and host communities together whenever possible.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('9', 'about', 'who_we_work_with', 'Smallholder Farmers', '', 'We help farmers improve soil and water management, access climate and market information, diversify production and connect to services, finance and buyers.', NULL, NULL, NULL, NULL, '30', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('10', 'about', 'who_we_work_with_gallery', 'Women & girls', '', '', 'assets/img/betterlifeint-source/programs/program-photo-6.jpg', NULL, NULL, 'A woman participating in a BetterLife community programme', '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('11', 'about', 'who_we_work_with_gallery', 'Refugees & smallholder farmers', '', '', 'assets/img/project-women-idps.jpg', NULL, NULL, 'A smallholder farmer tending crops', '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('12', 'about', 'where_we_work', 'Uganda', '', 'Uganda is where BetterLife began and where much of our work is based. Programmes include climate-resilient agriculture, refugee and host-community livelihoods, women’s economic empowerment, Green Libraries, tree nurseries, clean energy, water access, digital agriculture and BetterLife Agro Tourism Farm. Our West Nile work is coordinated through Yumbe and Bidi Bidi.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('13', 'about', 'where_we_work', 'South Sudan', '', 'Through our Juba office and field presence in Yambio, we work on food security, solar-powered irrigation, climate-resilient agriculture and practical livelihoods for young people, women and communities affected by conflict and displacement.', NULL, NULL, NULL, NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('14', 'about', 'where_we_work', 'Tanzania', '', 'Our Tanzania work is based in Kayanga Town, Karagwe District. Together with FADECO, we use schools, community radio and practical training to support climate education, health, green skills and youth enterprise.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('15', 'about', 'where_we_work', 'Ghana', '', 'In Ghana, our work focuses on youth leadership, climate action, sustainable livelihoods and community-led environmental solutions.', NULL, NULL, NULL, NULL, '30', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('16', 'about', 'where_we_work', 'Democratic Republic of Congo', '', 'Our work in the Democratic Republic of Congo supports young people and communities affected by poverty, conflict and displacement through livelihoods, environmental action and local participation.', NULL, NULL, NULL, NULL, '40', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('17', 'about', 'where_we_work_gallery', 'Ghana', '', '', 'assets/img/betterlifeint-source/projects/project-climate-education-alt.jpg', NULL, NULL, 'Climate education programme in Ghana', '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('18', 'about', 'where_we_work_gallery', 'Uganda', '', '', 'assets/img/betterlifeint-source/programs/program-photo-9.jpg', NULL, NULL, 'Community programme activity in Uganda', '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('19', 'about', 'journey', '2021', '', 'BetterLife International was founded in Uganda with USD 200 and a small team of young people.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('20', 'about', 'journey', '2022', '', 'The organisation expanded its community programmes and began establishing work in South Sudan and Tanzania.', NULL, NULL, NULL, NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('21', 'about', 'journey', '2023', '', 'BetterLife launched Soilla, expanded its school and environmental work and opened the Apala One Stop Youth Centre in Alebtong.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('22', 'about', 'journey', '2024', '', 'We started our communal farms, powered by clean energy. Our water access and livelihoods programmes continued to grow.', NULL, NULL, NULL, NULL, '30', '1', '2026-08-31 16:53:16', '2026-10-02 12:29:41'),
('23', 'about', 'journey', '2025', '', 'BetterLife deepened its work with women in Yumbe through the Foundation S-supported climate-resilience programme and strengthened BetterLife Agro Tourism Farm as a bridge from training to markets.', NULL, NULL, NULL, NULL, '40', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('24', 'about', 'journey', '2026', '', 'We began setting up our 20-acre communal farm, with clean energy supporting its operations. The Women’s Action Circle approach began expanding through Farm Radio International’s Green Leaf Platforms Uganda, and work continued on Soilla, Agribusiness Connekt, the BetterLife Climate Academy and regional youth innovation.', NULL, NULL, NULL, NULL, '50', '1', '2026-08-31 16:53:16', '2026-10-02 12:29:41'),
('25', 'about', 'guides', 'Dignity', '', 'People are partners with knowledge and ability, not passive recipients of help.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16');
INSERT INTO `content_items` (`id`, `page`, `section_key`, `title`, `subtitle`, `body`, `image`, `cta_label`, `cta_href`, `extra`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
('26', 'about', 'guides', 'Community Leadership', '', 'Those living with a problem should have real influence over the response.', NULL, NULL, NULL, NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('27', 'about', 'guides', 'Usefulness', '', 'An idea matters when people can put it to work in their own circumstances.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('28', 'about', 'guides', 'Accountability', '', 'We are responsible to the communities, partners and institutions that place their trust in us.', NULL, NULL, NULL, NULL, '30', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('29', 'about', 'guides', 'Inclusion', '', 'Participation must be designed around the barriers people face, not simply offered in theory.', NULL, NULL, NULL, NULL, '40', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('30', 'about', 'guides', 'Learning', '', 'We change course when evidence and experience show us a better way.', NULL, NULL, NULL, NULL, '50', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('31', 'programs', 'climate-resilient-agriculture', 'Women’s Climate Resilience in Yumbe', 'Implemented with support from Foundation S – The Sanofi Collective', 'Before the work began, we spoke with 100 women in Yumbe about the way climate pressure was changing their lives. Many were spending around four hours a day collecting water. Some travelled as far as 24 kilometres in search of firewood. Eighty-one per cent had experienced crop failure, and 63 per cent reported having withdrawn a child from school at some point because the household could not meet the cost.\n\nThose answers changed the shape of the project. This could not be a farming course alone.\n\nBetterLife worked with refugee, displaced and host-community women through local-language training and gardens where they could see each practice working. The women learnt composting, mulching, sack and box gardening, trellising, drought-tolerant crops, agroforestry and briquette-making. They received seedlings and support to use simple digital tools for soil and market information.\n\nAmong the 72 women who completed structured training, knowledge of climate-smart agriculture rose from 22 per cent to 92 per cent. Seventy-two per cent adopted sack or box gardening, 63 per cent took up composting, 54 per cent used mulching and 57 per cent introduced drought-tolerant crops. Participating households reported an average 35 per cent reduction in spending on vegetables as home production improved.\n\nThe figures matter, but so did the way the change happened. Women learnt in groups, saw the methods before risking their own resources and could return with questions after trying them at home. Confidence grew alongside knowledge.', NULL, 'Read the Project Story', 'blog.php', NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('32', 'programs', 'climate-resilient-agriculture', 'Green Leaf Platforms Uganda', 'In partnership with Farm Radio International', 'What happens after a radio programme ends?\n\nA woman may hear about a regenerative farming practice and understand it perfectly, yet still be unable to try it. She may not control the land, own a phone or have the materials to risk on an unfamiliar method. She may need to see the practice working nearby before she trusts it with a small harvest.\n\nBetterLife’s partnership with Farm Radio International is designed around that gap between receiving information and acting on it.\n\nUnder Green Leaf Platforms Uganda, radio and digital agricultural content is connected to Women’s Action Circles across 12 districts. These circles build on groups women already trust, including savings groups, farmer organisations, cooperatives and community networks.\n\nWomen listen, discuss what the information means in their setting, ask questions, visit demonstration plots and test practices together. Peer champions support those with limited access to phones or extension services. Women’s feedback also travels back into the programme, helping shape content around the questions and barriers they are actually facing.\n\nFarm Radio International brings its radio, digital and farmer-learning experience. BetterLife leads the women’s inclusion work on the ground, connecting listening to learning, practice and adoption.\n\nThe model grows from a lesson we first saw clearly in Yumbe: women adopt what they can see, and groups often carry change farther than individuals working alone.', NULL, 'Learn About Green Leaf Platforms', 'blog.php', NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('33', 'programs', 'climate-resilient-agriculture', 'BetterLife SPRING', 'Sustainable Powered Resilient Irrigation for Next Generation Farming', 'In South Sudan, farming families are expected to plan around rainfall that is becoming harder to predict. When rain stops too early, households lose food and the income they hoped to earn from the season.\n\nBetterLife SPRING combines solar-powered irrigation with practical training in soil health, crop planning and water management. Farmers, refugees and displaced families can produce more reliably through dry periods without depending on fuel-powered pumping.\n\nThe project brings together clean energy, food production and livelihoods. The aim is not simply to install irrigation equipment, but to help communities use it well, maintain it and turn more reliable production into stronger household security.', NULL, 'Explore BetterLife SPRING', 'blog.php', NULL, '20', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('34', 'programs', 'climate-resilient-agriculture', 'BetterLife Agro Tourism Farm', '', 'The farm is BetterLife’s working demonstration and market link. Farmers learn through solar-powered irrigation, greenhouse farming, beekeeping, dairy production and livestock rearing, then have a route to supply produce through BetterLife Agro Tourism Farm Ltd.', NULL, 'Discover the Farm', 'farm.php', NULL, '30', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('35', 'programs', 'green-skills-livelihoods', 'RISE', 'Market Inclusive Livelihood Pathways to Self-Reliance', 'RISE brings refugees and host-community members into the same training groups and local economy.\n\nParticipants learn practical skills such as poultry, farming, carpentry, tailoring, barbering and solar technology. They then receive mentorship, business support, market connections and access to small loans. Where appropriate, BetterLife helps participants who lack conventional collateral by acting as a guarantor.\n\nThe economic work also creates room for social cohesion. Refugees and host-community members build relationships as they train, save, trade and solve business problems together. Peacebuilding becomes part of ordinary economic life rather than a separate conversation in a workshop.\n\nAcross target groups, 78 per cent of participants moved into sustainable income pathways, 85 per cent reported improved refugee-host relations and food insecurity fell by 40 per cent.', NULL, 'Explore RISE', 'blog.php', NULL, '0', '1', '2026-08-31 16:53:16', '2026-10-06 12:01:41'),
('36', 'programs', 'green-skills-livelihoods', 'Agribusiness Connekt', '', 'Farmers are often trained to produce and then left alone at the point where business begins.\n\nAgribusiness Connekt links farmers and small agricultural enterprises to buyers, finance, services and market information. It helps producers understand what customers need, find opportunities beyond their immediate location and make better decisions about when and where to sell.\n\nThe platform also supports farmers trained through BetterLife programmes, giving them a route from production into longer-term enterprise.', NULL, 'Explore Agribusiness Connekt', 'blog.php', NULL, '10', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('37', 'programs', 'climate-education-youth-leadership', 'Green Libraries, Eco Labs and School Climate Clubs', '', 'Green Libraries and Eco Labs give learners access to books, digital resources and practical environmental activities. Students take part in school gardens, tree planting, waste separation, plastic banks, debates and public speaking.\n\nMore than 4,500 students have been engaged through school climate education, and BetterLife has supported over 20 Green Libraries and Eco Labs. Our school work has included Lake Victoria School Entebbe and Buddo Junior School.\n\nThe aim is not to turn every child into a climate expert. It is to make the subject understandable enough for them to connect it to their home, school and community, and confident enough for them to act.', NULL, 'Explore Green Libraries', 'blog.php', NULL, '0', '1', '2026-08-31 16:53:16', '2026-08-31 16:53:16'),
('38', 'programs', 'climate-education-youth-leadership', 'Apala One Stop Youth Centre', '', 'Talent exists in rural communities. Access often does not.\n\nThe Apala One Stop Youth Centre in Alebtong gives young people a place to read, use computers, learn digital skills and develop ideas. Launched in December 2023, the centre opened with ten computers, more than 3,000 books and space to serve around 400 young people.\n\nWe worked on the centre alongside COMESA, which supported its establishment with the Apala youth and community as part of its Silencing the Guns campaign, together with Save the Children, the Horn of Africa Youth Network, Epuka Ugaidi and Uganda’s National Youth Council. Before the launch on 21 December 2023, twenty young people were trained to manage the hub, alongside training in conflict prevention and peacebuilding.\n\nApala is a place for peacebuilding as well as learning. In a part of Northern Uganda still living with the legacy of conflict, it gives young people from different backgrounds a shared place to build skills, find mentors and lead.\n\nApala is both a learning centre and a statement about opportunity: where a young person is born should not decide how far their curiosity can take them.', NULL, 'Visit the Apala Story', 'blog.php', NULL, '10', '1', '2026-08-31 16:53:16', '2026-10-06 12:00:27'),
('39', 'programs', 'climate-education-youth-leadership', 'Climate Education and Youth Enterprise in Tanzania', '', 'Together with FADECO, BetterLife uses schools, community radio and practical training to reach young people and communities in Tanzania.\n\nFADECO, the Family Alliance for Development and Cooperation, has worked in Karagwe since 1993, across agriculture, environment, technology and community media. Its station, FADECO Radio on 100.8 FM, carries information on climate, agriculture, health and livelihoods into communities that formal training may not reach.\n\nBetterLife is a partner in Empowering Communities Through Climate Action, a FADECO project supported by AllPeopleBeHappy, contributing training tools and expertise in climate-smart agriculture and enterprise development. By July 2025 the project had trained more than 25 young entrepreneurs in climate-smart and green business and 30 community members in conservation tillage and agroforestry, planted more than 8,000 trees and reached more than 30,000 people through FADECO Radio.\n\nIn schools, climate clubs at Karadea Primary, Bohari Primary and Karagwe Secondary involve students in tree planting, waste management and environmental leadership.\n\nYoung people also learn skills such as reusable sanitary-pad production and liquid soap-making. The activities respond to health and dignity while opening small routes into enterprise.', NULL, 'Explore Our Work in Tanzania', 'blog.php', NULL, '20', '1', '2026-08-31 16:53:16', '2026-10-06 12:00:27'),
('40', 'programs', 'climate-education-youth-leadership', 'BetterLife Climate Leadership Academy', '', 'Climate negotiations can feel distant from the places already living with the consequences. The BetterLife Climate Leadership Academy helps young Africans understand those negotiations and connect them to what is happening in their own communities.\n\nParticipants learn about adaptation, climate finance, loss and damage, negotiations and advocacy. The academy also asks a more grounded question: what do these decisions mean for a farmer facing drought, a family displaced by floods or a young person trying to build a future?\n\nSupported by Moonshot, the virtual academy brings together young people from Uganda and across Africa to learn from experts and one another.', NULL, 'Explore the Climate Academy', 'blog.php', NULL, '30', '1', '2026-08-31 16:53:16', '2026-10-06 12:00:27'),
('41', 'programs', 'climate-education-youth-leadership', 'Climate Innovation Hackathons', '', 'BetterLife’s hackathon work gives young people a real problem, a team and room to build. Participants use technology, entrepreneurship and local knowledge to develop practical responses to climate and community challenges.\n\nWe work with KaKebe Technologies, a youth-led tech company in Lira City, on climate innovation hackathons and the Kakebe Tech Camp. BetterLife was among the partners that made Camp 2025 possible: a two-week residential camp at Jerusalem Heritage School in Lira, from 5 to 19 January 2025, which trained 257 young people from across East Africa.\n\nAlongside robotics, artificial intelligence, software development and entrepreneurship, the camp’s curriculum included Climate Action and Eco Action, using technology to promote sustainability, renewable energy, waste management and climate awareness. Every track ended with a working prototype, among them Natural Life, a website that educates and mobilises people towards sustainable choices.\n\nThe camp’s other partners and supporters included Huawei Technologies, Lira University, Jerusalem Heritage School, The Unlimited Youths, Lira City Council and Sky Water.', NULL, 'Explore Youth Innovation', 'blog.php', NULL, '40', '1', '2026-08-31 16:53:16', '2026-10-06 12:21:15'),
('42', 'programs', 'clean-energy-water-restoration', 'Community Tree Nurseries and Agroforestry', '', 'BetterLife-supported nurseries have raised more than 50,000 indigenous and fruit-tree seedlings, with over 20,000 distributed to schools, farmers and communities.\n\nFruit trees can contribute to nutrition and income. Indigenous trees protect soil, provide shade and support biodiversity. Through agroforestry, trees become part of the farm rather than competing with it.\n\nWe focus on what happens after distribution, including care, monitoring and survival. A seedling in the ground is a beginning, not a result by itself.', NULL, 'Explore Nature Restoration', 'blog.php', NULL, '0', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('43', 'programs', 'clean-energy-water-restoration', 'Clean Cooking and Biogas', '', 'Through BetterLife Renewable Pathways, we work on clean cooking in schools and refugee communities. Our biogas work is part of it.\n\nBetterLife has supported more than 48 household biogas systems. Families turn organic waste into cleaner cooking energy, reducing smoke inside the home and dependence on firewood and charcoal.\n\nThe process also produces an organic by-product that can be returned to the soil. One household system therefore connects waste, energy, health and farming.', NULL, 'Explore Clean Energy', 'blog.php', NULL, '10', '1', '2026-08-31 16:53:17', '2026-10-06 13:14:10'),
('44', 'programs', 'clean-energy-water-restoration', 'Water Access', '', 'BetterLife has supported 65 community boreholes. Reliable water reduces the time and distance people travel, improves household health and makes small-scale food production more possible.\n\nFor us, water is not a side issue. It sits at the centre of health, food, education and climate resilience.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('45', 'programs', 'clean-energy-water-restoration', 'BetterLife Renewable Pathways', '', 'Alongside clean cooking, we work with schools and communities on waste separation, plastic banks, recycling and the responsible reuse of materials. Four school plastic banks give learners a practical way to understand waste and participate in keeping plastics out of the environment.\n\nThe programme also explores safe, locally appropriate ways of recovering value from materials that would otherwise be dumped or burnt.', NULL, 'Explore Renewable Pathways', 'blog.php', NULL, '30', '1', '2026-08-31 16:53:17', '2026-10-06 13:14:46'),
('46', 'programs', 'clean-energy-water-restoration', 'Briquette-Making', '', 'Women and vulnerable households learn to make briquettes from suitable agricultural and organic waste. Briquettes can reduce dependence on firewood and charcoal while creating a product for household use or small-scale sale.\n\nFor a woman who spends hours collecting fuel, an alternative made closer to home can mean saved time as well as income.', NULL, NULL, NULL, NULL, '40', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('47', 'programs', 'digital-innovation', 'Soilla', '', 'Soilla is BetterLife’s digital agricultural advisory platform. It helps farmers access soil and crop guidance, climate information, market prices and agricultural services.\n\nFarmers can use the platform to better understand what may grow in their soil, monitor farm conditions, locate suppliers and experts and connect with other producers. The aim is to make information that is often expensive or distant more accessible to smallholder farmers.\n\nSoilla is paired with field training because owning a phone or receiving data does not automatically make a tool useful. Farmers need confidence, local support and information that fits their crops and circumstances.\n\nOur engagement with the World Food Programme has contributed to work around farmer information, verification and the responsible use of agricultural and climate data.', NULL, 'Explore Soilla', 'blog.php', NULL, '0', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('48', 'programs', 'digital-innovation', 'Agribusiness Connekt', '', 'Where Soilla supports production decisions, Agribusiness Connekt focuses on the business around the farm. It links producers to buyers, finance, services and market opportunities.\n\nTogether, the two platforms respond to a gap we see repeatedly: farmers learn how to produce, but remain disconnected from the systems that determine whether production becomes income.', NULL, 'Explore Agribusiness Connekt', 'blog.php', NULL, '10', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('49', 'programs', 'our-projects', 'Dovetail Impact Foundation', 'Growing without losing what made the work local', 'As BetterLife expanded, we had to answer a difficult question: how do we reach more people without becoming distant from the communities that shaped us?\n\nDovetail Impact Foundation has supported BetterLife through strategic acceleration and institutional strengthening. The relationship has helped us clarify our theory of change, strengthen how we measure and communicate impact and build more deliberate systems for growth and resource mobilisation.\n\nThis support sits behind all our programmes rather than inside one field project. It helps us examine the full path from training to application, from application to income and from individual progress to stronger community systems.\n\nGrowth, for BetterLife, is not simply a larger number. It is the ability to reach more people while protecting the dignity, usefulness and local ownership of the work.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('50', 'farm', 'on_the_farm', 'Solar-Powered Irrigation', '', 'Water is pumped and distributed using solar energy, helping crops survive when rainfall is unreliable.', NULL, NULL, NULL, NULL, '0', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17');
