('51', 'farm', 'on_the_farm', 'Greenhouse and Crop Farming', '', 'Farmers learn water-efficient production, soil management, crop care and methods suited to limited land.', NULL, NULL, NULL, NULL, '10', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('52', 'farm', 'on_the_farm', 'Dairy and Livestock', '', 'Livestock supports food, manure, household income and the farm’s dairy value chain.', NULL, NULL, NULL, NULL, '20', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('53', 'farm', 'on_the_farm', 'Beekeeping', '', 'Community beekeeping creates income while encouraging the protection of trees and flowering plants.', NULL, NULL, NULL, NULL, '30', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('54', 'farm', 'on_the_farm', 'Poultry and Aquaculture', '', 'Diversified production reduces the risk of depending on one crop or one season.', NULL, NULL, NULL, NULL, '40', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
('55', 'farm', 'on_the_farm', 'Seedlings', '', 'Participants receive free seedlings to establish gardens of their own and begin moving towards independent production.', NULL, NULL, NULL, NULL, '50', '1', '2026-08-31 16:53:17', '2026-08-31 16:53:17'),
