INSERT INTO `settings` (`setting_key`, `setting_value`) VALUES ('about_who_text', 'Denise Ayebare founded BetterLife International in Uganda in 2021. She was nineteen, and the organisation began with USD 200 and a small group of young people who were tired of watching communities receive short-term help while the conditions keeping them vulnerable remained unchanged.\n\nThey had seen farmers lose a season and start again with nothing. They had seen women carry the weight of food, water and household survival without access to finance or decision-making. They had seen young people complete training and still have no tools, customers or way into work. They had also seen how much knowledge already existed inside communities, often overlooked by programmes designed from far away.\n\nBetterLife was created to work differently.\n\nWhat began as a small youth-led initiative in Uganda now works across Uganda, South Sudan, Tanzania, Ghana and the Democratic Republic of Congo. The organisation brings together climate-resilient agriculture, livelihoods, clean energy, water, restoration, education, technology and market access.\n\nThe work has grown, but the starting point has remained the same: people closest to a problem must have a real hand in defining it, designing the response and deciding what success looks like.') ON DUPLICATE KEY UPDATE `setting_value` = VALUES(`setting_value`);
